211	    private Evaluator parsePseudoSelector() {
212	        final String pseudo = tq.consumeCssIdentifier();
213	        switch (pseudo) {
214	            case "lt":
215	                return new Evaluator.IndexLessThan(consumeIndex());
216	            case "gt":
217	                return new Evaluator.IndexGreaterThan(consumeIndex());
218	            case "eq":
219	                return new Evaluator.IndexEquals(consumeIndex());
220	            case "has":
221	                return has();
222	            case "is":
223	                return is();
224	            case "contains":
225	                return contains(false);
226	            case "containsOwn":
227	                return contains(true);
228	            case "containsWholeText":
229	                return containsWholeText(false);
230	            case "containsWholeOwnText":
231	                return containsWholeText(true);
232	            case "containsData":
233	                return containsData();
234	            case "matches":
235	                return matches(false);
236	            case "matchesOwn":
237	                return matches(true);
238	            case "matchesWholeText":
239	                return matchesWholeText(false);
240	            case "matchesWholeOwnText":
241	                return matchesWholeText(true);
242	            case "not":
243	                return not();
244	            case "lang":
245	                return lang();
246	            case "nth-child":
247	                return cssNthChild(false, false);
248	            case "nth-last-child":
249	                return cssNthChild(true, false);
250	            case "nth-of-type":
251	                return cssNthChild(false, true);
252	            case "nth-last-of-type":
253	                return cssNthChild(true, true);
254	            case "first-child":
255	                return new Evaluator.IsFirstChild();
256	            case "last-child":
257	                return new Evaluator.IsLastChild();
258	            case "first-of-type":
259	                return new Evaluator.IsFirstOfType();
260	            case "last-of-type":
261	                return new Evaluator.IsLastOfType();
262	            case "only-child":
263	                return new Evaluator.IsOnlyChild();
264	            case "only-of-type":
265	                return new Evaluator.IsOnlyOfType();
266	            case "empty":
267	                return new Evaluator.IsEmpty();
268	            case "blank":
269	                return new NodeEvaluator.BlankValue();
270	            case "root":
271	                return new Evaluator.IsRoot();
272	            case "scope":
273	                return new StructuralEvaluator.Scope();
274	            case "matchText": {
275	                @SuppressWarnings("deprecation") // :matchText remains supported until its scheduled removal.
276	                Evaluator.MatchText matchText = new Evaluator.MatchText();
277	                return matchText;
278	            }
279	            default:
280	                throw new Selector.SelectorParseException("Could not parse query '%s': unexpected token at '%s'", query, tq.remainder());
281	        }
282	    }
283	
284	    // ::comment etc
285	    private Evaluator parseNodeSelector() {
286	        final String pseudo = tq.consumeCssIdentifier();
287	        inNodeContext = true;  // Enter node context
288	
289	        Evaluator left;
290	        switch (pseudo) {
291	            case "node":
292	                left = new NodeEvaluator.InstanceType(Node.class, pseudo);
293	                break;
294	            case "leafnode":
295	                left = new NodeEvaluator.InstanceType(LeafNode.class, pseudo);
296	                break;
297	            case "text":
298	                left = new NodeEvaluator.InstanceType(TextNode.class, pseudo);
299	                break;
300	            case "comment":
301	                left = new NodeEvaluator.InstanceType(Comment.class, pseudo);
302	                break;
303	            case "data":
304	                left = new NodeEvaluator.InstanceType(DataNode.class, pseudo);
305	                break;
306	            case "cdata":
307	                left = new NodeEvaluator.InstanceType(CDataNode.class, pseudo);
308	                break;
309	            default:
310	                throw new Selector.SelectorParseException(
311	                    "Could not parse query '%s': unknown node type '::%s'", query, pseudo);
312	        }
313	
314	        // Handle following subclasses in node context (like ::comment:contains())
315	        Evaluator right;
316	        while ((right = parseSubclass()) != null) {
317	            left = and(left, right);
318	        }
319	
320	        inNodeContext = false;
321	        return left;
322	    }
323	
324	    private Evaluator byId() {
325	        String id = tq.consumeCssIdentifier();
326	        Validate.notEmpty(id);
327	        return new Evaluator.Id(id);
328	    }
329	
330	    private Evaluator byClass() {
331	        String className = tq.consumeCssIdentifier();
332	        Validate.notEmpty(className);
333	        return new Evaluator.Class(className.trim());
334	    }
335	
336	    private Evaluator byTag() {
337	        // todo - these aren't dealing perfectly with case sensitivity. For case sensitive parsers, we should also make
338	        // the tag in the selector case-sensitive (and also attribute names). But for now, normalize (lower-case) for
339	        // consistency - both the selector and the element tag
340	        String tagName = normalize(tq.consumeElementSelector());
341	        Validate.notEmpty(tagName);
342	
343	        // namespaces:
344	        if (tagName.startsWith("*|")) { // namespaces: wildcard match equals(tagName) or ending in ":"+tagName
345	            String plainTag = tagName.substring(2); // strip *|
346	            return new CombiningEvaluator.Or(
347	                new Evaluator.Tag(plainTag),
348	                new Evaluator.TagEndsWith(":" + plainTag)
349	            );
350	        } else if (tagName.endsWith("|*")) { // ns|*
351	            String ns = tagName.substring(0, tagName.length() - 2) + ":"; // strip |*, to ns:
352	            return new Evaluator.TagStartsWith(ns);
353	        } else if (tagName.contains("|")) { // flip "abc|def" to "abc:def"
354	            tagName = tagName.replace("|", ":");
355	        }
356	
357	        return new Evaluator.Tag(tagName);
358	    }
359	
360	    private Evaluator byAttribute() {
361	        try (TokenQueue cq = new TokenQueue(tq.chompBalanced('[', ']'))) {
362	            return evaluatorForAttribute(cq);
363	        }
364	    }
365	
366	    private Evaluator evaluatorForAttribute(TokenQueue cq) {
367	        cq.consumeWhitespace();
368	        String key = consumeAttributeKey(cq);
369	        key = normalize(key);
370	        Validate.notEmpty(key);
371	        Validate.isFalse(key.equals("abs:"), "Absolute attribute key must have a name");
372	        cq.consumeWhitespace();
373	        final Evaluator eval;
374	
375	        if (cq.isEmpty()) {
376	            if (key.startsWith("^"))
377	                eval = new Evaluator.AttributeStarting(key.substring(1));
378	            else if (key.equals("*")) // any attribute
379	                eval = new Evaluator.AttributeStarting("");
380	            else
381	                eval = new Evaluator.Attribute(key);
382	        } else if (cq.matchChomp("~=")) { // regex match; the remainder of the queue (less surrounding whitespace) is the pattern
383	            eval = new Evaluator.AttributeWithValueMatching(key, Regex.compile(cq.remainder().trim()));
384	        } else {
385	            final String op;
386	            if (cq.matchChomp("!=")) op = "!=";
387	            else if (cq.matchChomp("^=")) op = "^=";
388	            else if (cq.matchChomp("$=")) op = "$=";
389	            else if (cq.matchChomp("*=")) op = "*=";
390	            else if (cq.matchChomp("=")) op = "=";
391	            else throw new Selector.SelectorParseException(
392	                "Could not parse attribute query '%s': unexpected token at '%s'", query, cq.remainder());
393	
394	            cq.consumeWhitespace();
395	            final String rawValue = consumeAttributeValue(cq);
396	            final boolean quoted = !rawValue.isEmpty() && (rawValue.charAt(0) == '"' || rawValue.charAt(0) == '\'');
397	            // Quoted (CSS string) values keep their quotes and are decoded in the evaluator; bare values have their
398	            // CSS escapes decoded here, so escaped and unescaped forms of the same value match equally.
399	            final String value = quoted ? rawValue : TokenQueue.unescapeCss(rawValue);
400	            cq.consumeWhitespace();
401	
402	            // Quoted (CSS string) values compare case-sensitively by default; bare values keep jsoup's historical
403	            // case-insensitive compare. An 'i' or 's' modifier after the value overrides the default.
404	            boolean caseSensitive = quoted;
405	            if (!cq.isEmpty()) {
406	                String modifier = cq.consumeCssIdentifier();
407	                if (modifier.equalsIgnoreCase("s")) caseSensitive = true;
408	                else if (modifier.equalsIgnoreCase("i")) caseSensitive = false;
409	                else throw new Selector.SelectorParseException(
410	                    "Could not parse attribute query '%s': unexpected token at '%s'", query, modifier + cq.remainder());
411	                cq.consumeWhitespace();
412	                if (!cq.isEmpty())
413	                    throw new Selector.SelectorParseException(
414	                        "Could not parse attribute query '%s': unexpected token at '%s'", query, cq.remainder());
415	            }
416	
417	            switch (op) {
418	                case "=":
419	                    eval = new Evaluator.AttributeWithValue(key, value, caseSensitive);
420	                    break;
421	                case "!=":
422	                    eval = new Evaluator.AttributeWithValueNot(key, value, caseSensitive);
423	                    break;
424	                case "^=":
425	                    eval = new Evaluator.AttributeWithValueStarting(key, value, caseSensitive);
426	                    break;
427	                case "$=":
428	                    eval = new Evaluator.AttributeWithValueEnding(key, value, caseSensitive);
429	                    break;
430	                case "*=":
431	                    eval = new Evaluator.AttributeWithValueContaining(key, value, caseSensitive);
432	                    break;
433	                default:
434	                    throw new Selector.SelectorParseException(
435	                        "Could not parse attribute query '%s': unexpected token at '%s'", query, cq.remainder());
436	            }
437	        }
438	        return eval;
439	    }
440	
441	    /**
442	     Consumes an attribute key off the queue, up to (but not including) whitespace or a comparison operator. CSS
443	     escapes in the key are decoded.
444	     */
445	    private String consumeAttributeKey(TokenQueue cq) {
446	        StringBuilder sb = StringUtil.borrowBuilder();
447	        OUT: while (!cq.isEmpty()) {
448	            if (cq.matchesWhitespace()) break;
449	            for (String eval : AttributeEvals) {
450	                if (cq.matches(eval)) break OUT;
451	            }
452	            if (cq.matches('\\')) cq.consumeCssEscapeSequence(sb);
453	            else sb.append(cq.consume());
454	        }
455	        return StringUtil.releaseBuilder(sb);
456	    }
457	
458	    /**
459	     Consumes an attribute value off the queue: either a quoted string (returned with its quotes, for decoding in the
460	     evaluator), or a bare value running to the next whitespace or the end of the queue.
461	     */
462	    private String consumeAttributeValue(TokenQueue cq) {
463	        if (cq.isEmpty()) return "";
464	
465	        if (cq.matches('"') || cq.matches('\'')) {
466	            StringBuilder sb = StringUtil.borrowBuilder();
467	            char quote = cq.consume();
468	            sb.append(quote);
469	            boolean closed = false;
470	            while (!cq.isEmpty()) {
471	                char c = cq.consume();
472	                sb.append(c);
473	                if (c == '\\' && !cq.isEmpty()) {
474	                    sb.append(cq.consume()); // keep the escaped character with its escape, for balanced decoding
475	                } else if (c == quote) {
476	                    closed = true;
477	                    break;
478	                }
479	            }
480	            if (!closed) {
481	                StringUtil.releaseBuilderVoid(sb);
482	                throw new Selector.SelectorParseException("Quoted value must have content");
483	            }
484	            return StringUtil.releaseBuilder(sb);
485	        }
486	
487	        // bare value, up to the next whitespace or the end of the queue
488	        StringBuilder sb = StringUtil.borrowBuilder();
489	        while (!cq.isEmpty() && !cq.matchesWhitespace()) sb.append(cq.consume());
490	        return StringUtil.releaseBuilder(sb);
491	    }
492	
493	    //pseudo selectors :first-child, :last-child, :nth-child, ...
494	    private static final Pattern NthStepOffset = Pattern.compile("(([+-])?(\\d+)?)n(\\s*([+-])?\\s*\\d+)?", Pattern.CASE_INSENSITIVE);
495	    private static final Pattern NthOffset = Pattern.compile("([+-])?(\\d+)");
496	
497	    private Evaluator cssNthChild(boolean last, boolean ofType) {
498	        String raw = consumeParens(); // arg is like "odd", or "-n+2", within nth-child(odd), optionally followed by " of S"
499	        final int ofIdx = indexOfOfClause(raw);
500	        final String arg = normalize(ofIdx >= 0 ? raw.substring(0, ofIdx) : raw);
501	        final boolean hasOf = ofIdx >= 0;
502	
503	        if (hasOf && ofType)
504	            throw new Selector.SelectorParseException(
505	                "Could not parse query '%s': 'of S' is only supported by :nth-child and :nth-last-child", query);
506	
507	        final int step, offset;
508	        if ("odd".equals(arg)) {
509	            step = 2;
510	            offset = 1;
511	        } else if ("even".equals(arg)) {
512	            step = 2;
513	            offset = 0;
514	        } else {
515	            Matcher stepOffsetM, stepM;
516	            if ((stepOffsetM = NthStepOffset.matcher(arg)).matches()) {
517	                if (stepOffsetM.group(3) != null) // has digits, like 3n+2 or -3n+2
518	                    step = Integer.parseInt(stepOffsetM.group(1).replaceFirst("^\\+", ""));
519	                else // no digits, might be like n+2, or -n+2. if group(2) == "-", it’s -1;
520	                    step = "-".equals(stepOffsetM.group(2)) ? -1 : 1;
521	                offset =
522	                    stepOffsetM.group(4) != null ? Integer.parseInt(stepOffsetM.group(4).replaceFirst("^\\+", "")) : 0;
523	            } else if ((stepM = NthOffset.matcher(arg)).matches()) {
524	                step = 0;
525	                offset = Integer.parseInt(stepM.group().replaceFirst("^\\+", ""));
526	            } else {
527	                throw new Selector.SelectorParseException("Could not parse nth-index '%s': unexpected format", arg);
528	            }
529	        }
530	
531	        if (hasOf) {
532	            String subQuery = raw.substring(ofIdx + 2).trim(); // skip the "of" keyword
533	            Validate.notEmpty(subQuery, ":nth-child(An+B of S) selector S must not be empty");
534	            Evaluator selector = parse(subQuery); // a comma-separated complex selector list; validates the full grammar
535	            return new Evaluator.IsNthChildOf(step, offset, last, selector);
536	        }
537	
538	        return ofType
539	            ? (last ? new Evaluator.IsNthLastOfType(step, offset) : new Evaluator.IsNthOfType(step, offset))
540	            : (last ? new Evaluator.IsNthLastChild(step, offset) : new Evaluator.IsNthChild(step, offset));
541	    }
542	
543	    /**
544	     Finds the index of the {@code of} keyword separating An+B from the selector list in an
545	     {@code :nth-child(An+B of S)} argument. The keyword must be bounded on both sides by whitespace, and is not
546	     matched inside quoted strings (so attribute values containing " of " are preserved).
547	     @return the index of the 'o' in 'of', or -1 if there is no of clause
548	     */
549	    private static int indexOfOfClause(String arg) {
550	        boolean inSingle = false;
551	        boolean inDouble = false;
552	        boolean prevEscaped = false;
553	        for (int i = 0; i < arg.length(); i++) {
554	            char c = arg.charAt(i);
555	            if (c == '\\' && i + 1 < arg.length()) {
556	                i++; // skip the escaped char
557	                prevEscaped = true;
558	                continue;
559	            }
560	            if (!inDouble && c == '\'')
561	                inSingle = !inSingle;
562	            else if (!inSingle && c == '"')
563	                inDouble = !inDouble;
564	
565	            if (!inSingle && !inDouble && !prevEscaped
566	                && i > 0 && StringUtil.isWhitespace(arg.charAt(i - 1))
567	                && arg.regionMatches(true, i, "of", 0, 2)
568	                && i + 2 < arg.length() && StringUtil.isWhitespace(arg.charAt(i + 2))) {
569	                return i;
570	            }
571	            prevEscaped = false;
572	        }
573	        return -1;
574	    }
575	
576	    private String consumeParens() {
577	        return tq.chompBalanced('(', ')');
578	    }
579	
580	    private int consumeIndex() {
581	        String index = consumeParens().trim();
582	        Validate.isTrue(StringUtil.isNumeric(index), "Index must be numeric");
583	        return Integer.parseInt(index);
584	    }
585	
586	    // pseudo selector :has(el)
587	    private Evaluator has() {
588	        int savedDepth = relativeDepth;
589	        relativeDepth = savedDepth + 1; // :has() takes a relative selector list, anchored to each candidate
590	        try {
591	            return parseNested(StructuralEvaluator.Has::new, ":has() must have a selector");
592	        } finally {
593	            relativeDepth = savedDepth;
594	        }
595	    }
596	
597	    // pseudo selector :is()
598	    private Evaluator is() {
599	        int savedDepth = relativeDepth;
600	        relativeDepth = 0; // :is() takes an absolute selector list; it does not inherit :has()'s relative anchor
601	        try {
602	            return parseNested(StructuralEvaluator.Is::new, ":is() must have a selector");
603	        } finally {
604	            relativeDepth = savedDepth;
605	        }
606	    }
607	
608	    private Evaluator parseNested(Function<Evaluator, Evaluator> func, String err) {
609	        Validate.isTrue(tq.matchChomp('('), err);
610	        Evaluator eval = parseSelectorGroup();
611	        Validate.isTrue(tq.matchChomp(')'), err);
612	        return func.apply(eval);
613	    }
614	
615	    /** Tests whether a branch's leftmost compound explicitly supplies its own {@code :scope} anchor (e.g.
616	     *  {@code :scope > p} or {@code :scope:not(.x)}), so the implicit relative descendant anchor is not duplicated.
617	     *  A :scope buried inside an :is()/:not() filter is a condition, not the chain anchor, and returns false. */
618	    private static boolean containsScope(Evaluator eval) {
619	        if (eval instanceof StructuralEvaluator.Scope)
620	            return true;
621	        if (eval instanceof CombiningEvaluator.And) {
622	            for (Evaluator inner : ((CombiningEvaluator.And) eval).evaluators) {
623	                if (containsScope(inner))
624	                    return true;
625	            }
626	        }
627	        return false;
628	    }
629	
630	    // pseudo selector :contains(text), containsOwn(text)
631	    private Evaluator contains(boolean own) {
632	        String query = own ? ":containsOwn" : ":contains";
633	        String searchText = TokenQueue.unescape(consumeParens());
634	        Validate.notEmpty(searchText, query + "(text) query must not be empty");
635	
636	        if (inNodeContext)
637	            return new NodeEvaluator.ContainsValue(searchText);
638	
639	        return own
640	            ? new Evaluator.ContainsOwnText(searchText)
641	            : new Evaluator.ContainsText(searchText);
642	    }
643	
644	    private Evaluator containsWholeText(boolean own) {
645	        String query = own ? ":containsWholeOwnText" : ":containsWholeText";
646	        String searchText = TokenQueue.unescape(consumeParens());
647	        Validate.notEmpty(searchText, query + "(text) query must not be empty");
648	        return own
649	            ? new Evaluator.ContainsWholeOwnText(searchText)
650	            : new Evaluator.ContainsWholeText(searchText);
651	    }
652	
653	    // pseudo selector :containsData(data)
654	    private Evaluator containsData() {
655	        String searchText = TokenQueue.unescape(consumeParens());
656	        Validate.notEmpty(searchText, ":containsData(text) query must not be empty");
657	        return new Evaluator.ContainsData(searchText);
658	    }
659	
660	    // :matches(regex), matchesOwn(regex)
661	    private Evaluator matches(boolean own) {
662	        String query = own ? ":matchesOwn" : ":matches";
663	        String regex = consumeParens(); // don't unescape, as regex bits will be escaped
664	        Validate.notEmpty(regex, query + "(regex) query must not be empty");
665	        Regex pattern = Regex.compile(regex);
666	
667	        if (inNodeContext)
668	            return new NodeEvaluator.MatchesValue(pattern);
669	
670	        return own
671	            ? new Evaluator.MatchesOwn(pattern)
672	            : new Evaluator.Matches(pattern);
673	    }
674	
675	    // :matches(regex), matchesOwn(regex)
676	    private Evaluator matchesWholeText(boolean own) {
677	        String query = own ? ":matchesWholeOwnText" : ":matchesWholeText";
678	        String regex = consumeParens(); // don't unescape, as regex bits will be escaped
679	        Validate.notEmpty(regex, query + "(regex) query must not be empty");
680	
681	        Regex pattern = Regex.compile(regex);
682	        return own
683	            ? new Evaluator.MatchesWholeOwnText(pattern)
684	            : new Evaluator.MatchesWholeText(pattern);
685	    }
686	
687	    // :not(selector)
688	    private Evaluator not() {
689	        String subQuery = consumeParens();
690	        Validate.notEmpty(subQuery, ":not(selector) subselect must not be empty");
691	
692	        return new StructuralEvaluator.Not(parse(subQuery));
693	    }
694	
695	    // pseudo selector :lang(en), :lang("en-US")
696	    private Evaluator lang() {
697	        String arg = consumeParens().trim(); // whitespace just inside the parens is ignored
698	        Validate.notEmpty(arg, ":lang() must have a language range");
699	
700	        final String range;
701	        final char first = arg.charAt(0);
702	        if (first == '\'' || first == '"') {
703	            // a quoted range must close at the very end of the argument, with nothing after it
704	            Validate.isTrue(arg.length() > 1 && arg.charAt(arg.length() - 1) == first,
705	                ":lang() has an unclosed quote or trailing content after the language range");
706	            range = arg.substring(1, arg.length() - 1);
707	        } else {
708	            range = arg;
709	        }
710	
711	        Validate.notEmpty(range, ":lang() must have a language range");
712	        for (int i = 0; i < range.length(); i++) {
713	            char c = range.charAt(i);
714	            Validate.isFalse(c == ',' || StringUtil.isWhitespace(c),
715	                ":lang() language range must not contain whitespace or commas");
716	        }
717	        return new Evaluator.Lang(range);
718	    }
719	
720	    @Override
721	    public String toString() {
722	        return query;
723	    }
724	
725	    @Override
726	    public void close() {
727	        tq.close();
728	    }
729	}
