import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.select.Elements;
import org.jsoup.select.Selector;

public class NthOfHarness {
    static String html = "<div id=a>" +
        "<b>1</b><i>2</i><b class='x'>3</b><span>4</span><b>5</b><i class='x'>6</i><b>7</b>" +
        "</div>" +
        "<div id=b>" +
        "<em>x</em><b>y</b><b>z</b>" +
        "</div>";

    static void check(String q) {
        try {
            Document doc = Jsoup.parse(html);
            Elements els = doc.select(q);
            StringBuilder sb = new StringBuilder();
            for (var e : els) sb.append(e.tagName()).append(e.className().isEmpty()?"":"."+e.className()).append("=").append(e.text()).append("  ");
            System.out.printf("%-40s -> %s%n", q, sb);
        } catch (Exception e) {
            System.out.printf("%-40s -> THROW %s: %s%n", q, e.getClass().getSimpleName(), e.getMessage());
        }
    }

    public static void main(String[] a) {
        check(":nth-child(2 of b)");          // second b in each parent: div#a b=3, div#b b=z
        check(":nth-child(odd of b)");        // b positions 1,3: 1,5? b's: 1,3,5,7 -> 1,5
        check(":nth-child(even of b)");       // b=3,7
        check(":nth-last-child(1 of b)");     // last b per parent: 7, z
        check(":nth-last-child(-n+2 of b)");  // last 2 b's: 5,7 and y,z
        check(":nth-child(2 of b, i)");       // among b/i in doc order: items: b1,i2,b3,i6,b7 -> 2nd=i2, 4th=i6
        check(":nth-child(2 of .x)");         // .x siblings: b.x=3 (1st), i.x=6 (2nd) -> i6
        check(":nth-child(1 of b, b)");       // duplicate branches dedup count: first b=1
        check(":nth-child(1 of span)");       // span=4
        check(":nth-child(0n+2 of b)");
        check(":nth-child( 2 of b )");        // whitespace
        check("div :nth-child(2 of b)");
        // combinators in S
        check(":nth-child(1 of div > b)");    // S scoped to whole doc root: b direct child of div -> first b each
        check(":nth-child(1 of b.x)");
        check(":nth-child(1 of :not(b))");    // first non-b element child: i2
        check(":nth-child(1 of [class])");    // first classed sibling: b.x=3
        // nested pseudo in S
        check(":nth-child(2 of b:nth-child(odd))"); // b's that are odd overall: b1(pos1),b5(pos5)... 2nd matching b=b5
        // outer comma layering
        check("i, :nth-child(1 of b)");       // union dedup
        // comma inside S must not split outer
        check(":nth-child(1 of b, i), span");
        // quotes / escapes / brackets with " of " inside
        check(":nth-child(1 of [data-x=\"a of b\"])");
        // errors
        check(":nth-child( of b)");
        check(":nth-child(2 of)");
        check(":nth-child(2 of )");
        check(":nth-child(2 of b");
        check(":nth-child( of)");
        check(":nth-child()");
        check(":nth-child(2 of > b)");        // combinator with no left side
        check(":nth-child(2 of b >)");        // dangling combinator
        check(":nth-child(b of b)");          // illegal expression
        check(":nth-child(2n of b)");
        check(":nth-of-type(2 of b)");        // not supported
        // compat: without of
        check(":nth-child(2)");
        check(":nth-last-child(2)");
        check("b.x");
        check("[class=x]");
    }
}
