import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.select.Elements;

public class H2 {
    static void check(String html, String q) {
        try {
            Document doc = Jsoup.parse(html);
            Elements els = doc.select(q);
            StringBuilder sb = new StringBuilder();
            for (var e : els) sb.append(e.tagName()).append("=").append(e.text()).append("  ");
            System.out.printf("%-45s -> %s%n", q, sb);
        } catch (Exception e) {
            System.out.printf("%-45s -> THROW %s%n", q, e.getMessage());
        }
    }
    public static void main(String[] a) {
        String html = "<div id=a><b>1</b><b>x of y</b><b>3</b></div>";
        // of inside nested pseudo parens, no quote protection possible
        check(html, ":nth-child(2 of b:contains( of ))");
        check(html, ":nth-child(2 of b:containsOwn( of ))");
        check(html, ":nth-child(2 of b:matches( of ))");
        check(html, ":nth-child(2 of b:has( of ))"); // should be parse error for OTHER reason (has bad) but not wrong split
        // of inside square brackets quoted (should work)
        check(html, ":nth-child(2 of b[data-x=\" of \"])");
        // leading combinators in S after comma
        check(html, ":nth-child(1 of b, > i)");
        check(html, ":nth-child(1 of + b)");
        check(html, ":nth-child(1 of ~ b)");
        // sub-element context: S scope
        Document doc = Jsoup.parse("<div id=outer><section><div id=inner><b>1</b><b>2</b></div></section></div>");
        Elements inner = doc.select("#inner");
        System.out.println("context select nth(2 of b): " + inner.select(":nth-child(2 of b)").eachText());
        System.out.println("context select nth(1 of section b): " + inner.select(":nth-child(1 of section b)").eachText());
        System.out.println("context nth(1 of div b): " + inner.select(":nth-child(1 of div b)").eachText());

        // multi-doc isolation
        Document d1 = Jsoup.parse("<div><b>1</b><b>2</b></div>");
        Document d2 = Jsoup.parse("<div><b>a</b><b>b</b><b>c</b></div>");
        System.out.println("d1: " + d1.select(":nth-child(2 of b)").eachText() + " d2: " + d2.select(":nth-child(2 of b)").eachText());
        System.out.println("d1 again: " + d1.select(":nth-child(2 of b)").eachText());

        // round trip
        Document d3 = Jsoup.parse("<div><b>1</b><i>2</i><b>3</b></div>");
        String q = ":nth-child(2 of b, i)";
        var r1 = d3.select(q).eachText();
        Document d4 = Jsoup.parse(d3.html());
        var r2 = d4.select(q).eachText();
        System.out.println("roundtrip equal: " + r1.equals(r2) + " " + r1 + " " + r2);

        // empty doc / no match
        System.out.println("empty: " + Jsoup.parse("").select(":nth-child(1 of b)").size());
        System.out.println("nomatch: " + Jsoup.parse("<p>x</p>").select(":nth-child(1 of b)").size());

        // failure leaves doc usable
        Document d5 = Jsoup.parse(html);
        try { d5.select(":nth-child(2 of )"); } catch (Exception e) { System.out.println("thrown: " + e.getClass().getSimpleName()); }
        System.out.println("after fail: " + d5.select("b").eachText() + " | html len " + d5.html().length());

        // dedup outer branches, document order
        Document d6 = Jsoup.parse("<div><b>1</b><i>2</i><b>3</b></div>");
        System.out.println(d6.select(":nth-child(odd of b), b").eachText());
    }
}
